//! Port of fontTools' `Tests/varLib/featureVars_test.py`, and the doctests of
//! `fontTools.varLib.featureVars`.
//!
//! The fonts that the tests build with `varLib._add_fvar` and feaLib are
//! fixtures, generated by `tools/reference/featurevars_fixtures.py`. The `lazy`
//! parameters of fontTools' tests are not ported: tables are always fully
//! loaded here.

#![allow(clippy::type_complexity)]

mod common;

use common::*;
use fontoxide_misc::py::format_g;
use fontoxide_ttlib::beyond64k::{
	ConvertOptions, convert_layout_formats, lower_tables, upper_tables,
};
use fontoxide_ttlib::ot::types as ot;
use fontoxide_ttlib::tables::{Gpos, Gsub, Os2};
use fontoxide_ttlib::{Font, Table, TableType, Tag};
use fontoxide_varlib::feature_vars::{
	AxisBox, OtlTable, Region, Substitution, add_feature_variations, add_feature_variations_raw,
	overlay_box, overlay_feature_variations,
};

const RVRN: Tag = Tag::new(b"rvrn");
const RCLT: Tag = Tag::new(b"rclt");
const CCMP: Tag = Tag::new(b"ccmp");
const RLIG: Tag = Tag::new(b"rlig");

fn data(name: &str) -> String {
	format!(
		"{}/tests/data/feature_vars/{name}",
		env!("CARGO_MANIFEST_DIR")
	)
}

/// The `varfont` fixture, with an OS/2 table whose `usMaxContext` is 0.
fn varfont() -> TestResult<Font> {
	let mut font = font_from_ttx(&data("varfont.ttx"))?;
	font.insert(Box::new(Os2::default()));
	Ok(font)
}

fn bx(axes: &[(&str, (f64, f64))]) -> AxisBox {
	axes.iter().map(|(t, r)| ((*t).to_owned(), *r)).collect()
}

fn subst(pairs: &[(&str, &str)]) -> Substitution {
	pairs
		.iter()
		.map(|(a, b)| ((*a).to_owned(), (*b).to_owned()))
		.collect()
}

fn rules(rules: &[(&[AxisBox], Substitution)]) -> Vec<(Region, Substitution)> {
	rules.iter().map(|(r, s)| (r.to_vec(), s.clone())).collect()
}

fn gsub(font: &mut Font) -> TestResult<&mut ot::GSUB> {
	Ok(&mut font.require::<Gsub>()?.table)
}

fn variations(gsub: &ot::GSUB) -> TestResult<&ot::FeatureVariations> {
	Ok(gsub
		.feature_variations
		.as_deref()
		.ok_or("no FeatureVariations")?)
}

fn feature_list(gsub: &ot::GSUB) -> TestResult<&ot::FeatureList> {
	Ok(gsub.feature_list.as_deref().ok_or("no FeatureList")?)
}

fn lookups(gsub: &ot::GSUB) -> TestResult<&[Option<Box<ot::Lookup>>]> {
	Ok(&gsub.lookup_list.as_deref().ok_or("no LookupList")?.lookup)
}

fn feature_tags(gsub: &ot::GSUB) -> TestResult<Vec<Tag>> {
	Ok(feature_list(gsub)?
		.feature_record
		.iter()
		.map(|f| f.feature_tag)
		.collect())
}

fn substitution(record: &ot::FeatureVariationRecord) -> TestResult<&ot::FeatureTableSubstitution> {
	Ok(record
		.feature_table_substitution
		.as_deref()
		.ok_or("no FeatureTableSubstitution")?)
}

fn lookup_list_index(record: &ot::FeatureTableSubstitutionRecord) -> TestResult<Vec<u16>> {
	Ok(record
		.feature
		.as_deref()
		.ok_or("no Feature")?
		.lookup_list_index
		.clone())
}

/// The glyph ID mapping of the single substitution of a lookup.
fn single_mapping(gsub: &ot::GSUB, index: usize) -> TestResult<Vec<(u32, u32)>> {
	let lookup = lookups(gsub)?[index].as_deref().ok_or("no Lookup")?;
	let Some(ot::LookupSubTable::SingleSubst(subtable)) = lookup.sub_table[0].as_deref() else {
		return Err("not a SingleSubst".into());
	};
	Ok(subtable.mapping.iter().map(|(&a, &b)| (a, b)).collect())
}

// Glyph IDs of the `varfont` fixture.
const A: u32 = 2;
const B: u32 = 3;
const A_ALT: u32 = 4;
const B_ALT: u32 = 5;

/// `_substitution_features`.
fn substitution_features(gsub: &ot::GSUB, rec_index: usize) -> TestResult<Vec<(u16, Tag)>> {
	let tags = feature_tags(gsub)?;
	let record = &variations(gsub)?.feature_variation_record[rec_index];
	Ok(substitution(record)?
		.substitution_record
		.iter()
		.map(|r| (r.feature_index, tags[usize::from(r.feature_index)]))
		.collect())
}

/// `roundtrip`: compiles a table and decompiles it again.
fn roundtrip<T: TableType + Table>(font: &mut Font) -> TestResult {
	let data = font.table_data(T::TAG)?;
	let table = T::decompile(&data, font)?;
	font.insert(Box::new(table));
	Ok(())
}

fn one_rule(axes: &[(&str, (f64, f64))], pairs: &[(&str, &str)]) -> Vec<(Region, Substitution)> {
	vec![(vec![bx(axes)], subst(pairs))]
}

#[test]
fn test_add_feature_variations() -> TestResult {
	let mut font = varfont()?;
	assert!(!font.has::<Gsub>());

	assert_eq!(font.require::<Os2>()?.us_max_context, 0);
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (0.5, 1.0))], &[("A", "A.alt")]),
		&[RVRN],
	)?;
	assert_eq!(font.require::<Os2>()?.us_max_context, 1);

	assert!(font.has::<Gsub>());
	let gsub = gsub(&mut font)?;

	let scripts = &gsub
		.script_list
		.as_deref()
		.ok_or("no ScriptList")?
		.script_record;
	assert_eq!(scripts.len(), 1);
	assert_eq!(scripts[0].script_tag, Tag::new(b"DFLT"));

	assert_eq!(feature_tags(gsub)?, [RVRN]);

	let lookups = lookups(gsub)?;
	assert_eq!(lookups.len(), 1);
	let lookup = lookups[0].as_deref().ok_or("no Lookup")?;
	assert_eq!(lookup.lookup_type, 1);
	assert_eq!(lookup.sub_table.len(), 1);
	assert_eq!(single_mapping(gsub, 0)?, [(A, A_ALT)]);

	let records = &variations(gsub)?.feature_variation_record;
	assert_eq!(records.len(), 1);
	let fvr = &records[0];
	let conditions = &fvr
		.condition_set
		.as_deref()
		.ok_or("no ConditionSet")?
		.condition_table;
	assert_eq!(conditions.len(), 1);
	let Some(ot::ConditionTable::Format1(cst)) = conditions[0].as_deref() else {
		return Err("not a format 1 condition".into());
	};
	assert_eq!(cst.axis_index, 0);
	assert_eq!(cst.filter_range_min_value, 0.5);
	assert_eq!(cst.filter_range_max_value, 1.0);
	let records = &substitution(fvr)?.substitution_record;
	assert_eq!(records.len(), 1);
	assert_eq!(records[0].feature_index, 0);
	assert_eq!(lookup_list_index(&records[0])?, [0]);
	Ok(())
}

#[test]
fn test_add_feature_variations_existing_variable_feature() -> TestResult {
	let mut font = varfont()?;
	let rule = one_rule(&[("wght", (0.5, 1.0))], &[("A", "A.alt")]);
	add_feature_variations(&mut font, &rule, &[RVRN])?;

	let gsub = gsub(&mut font)?;
	assert_eq!(feature_tags(gsub)?, [RVRN]);
	assert_eq!(variations(gsub)?.feature_variation_record.len(), 1);
	assert_eq!(substitution_features(gsub, 0)?, [(0, RVRN)]);

	// Can't add feature variations for an existing feature tag that already has
	// some, in this case the default 'rvrn'.
	let error = add_feature_variations(&mut font, &rule, &[RVRN])
		.err()
		.ok_or("expected an error")?;
	assert_eq!(
		error.to_string(),
		"FeatureVariations already exist for feature tag(s): {'rvrn'}"
	);
	Ok(())
}

#[test]
fn test_add_feature_variations_new_feature() -> TestResult {
	let mut font = varfont()?;
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (0.5, 1.0))], &[("A", "A.alt")]),
		&[RVRN],
	)?;

	let g = gsub(&mut font)?;
	assert_eq!(feature_tags(g)?, [RVRN]);
	assert_eq!(lookups(g)?.len(), 1);
	assert_eq!(variations(g)?.feature_variation_record.len(), 1);
	assert_eq!(substitution_features(g, 0)?, [(0, RVRN)]);

	// We can add feature variations for a feature tag that does not have any
	// feature variations yet.
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (-1.0, 0.0))], &[("B", "B.alt")]),
		&[RCLT],
	)?;

	let g = gsub(&mut font)?;
	// 'rclt' is now first (index 0) in the feature list sorted by tag, and
	// 'rvrn' is second (index 1).
	assert_eq!(feature_tags(g)?, [RCLT, RVRN]);
	assert_eq!(lookups(g)?.len(), 2);
	assert_eq!(variations(g)?.feature_variation_record.len(), 2);
	// The new 'rclt' feature variation record is appended to the end; the
	// feature index of the 'rvrn' feature table substitution record is now 1.
	assert_eq!(substitution_features(g, 0)?, [(1, RVRN)]);
	assert_eq!(substitution_features(g, 1)?, [(0, RCLT)]);
	Ok(())
}

#[test]
fn test_add_feature_variations_prepend_lookup() -> TestResult {
	for same_condition in [false, true] {
		let mut font = varfont()?;
		let condition = (0.5, 1.0);
		add_feature_variations(
			&mut font,
			&one_rule(&[("wght", condition)], &[("A", "A.alt")]),
			&[CCMP],
		)?;
		let original = |font: &mut Font| -> TestResult<Vec<u16>> {
			let g = gsub(font)?;
			let record = &variations(g)?.feature_variation_record[0];
			lookup_list_index(&substitution(record)?.substitution_record[0])
		};
		assert_eq!(original(&mut font)?, [0]);

		let new_condition = if same_condition {
			condition
		} else {
			(-1.0, 0.0)
		};
		add_feature_variations(
			&mut font,
			&one_rule(&[("wght", new_condition)], &[("B", "B.alt")]),
			&[RVRN],
		)?;
		assert_eq!(original(&mut font)?, [1], "same_condition={same_condition}");
		let g = gsub(&mut font)?;
		assert_eq!(single_mapping(g, 0)?, [(B, B_ALT)]);
		assert_eq!(single_mapping(g, 1)?, [(A, A_ALT)]);
	}
	Ok(())
}

#[test]
fn test_add_feature_variations_existing_condition() -> TestResult {
	let mut font = varfont()?;

	// Add a feature variation for the 'ccmp' feature tag with a condition.
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (0.5, 1.0))], &[("A", "A.alt")]),
		&[CCMP],
	)?;

	// There is now one feature record, one lookup, and one feature variation
	// record.
	let g = gsub(&mut font)?;
	assert_eq!(feature_tags(g)?, [CCMP]);
	assert_eq!(lookups(g)?.len(), 1);
	assert_eq!(variations(g)?.feature_variation_record.len(), 1);
	assert_eq!(substitution_features(g, 0)?, [(0, CCMP)]);

	// Add a feature variation for the 'rlig' feature tag with the same condition.
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (0.5, 1.0))], &[("B", "B.alt")]),
		&[RLIG],
	)?;

	// There are now two feature records, two lookups, and one feature variation
	// record, since the condition is the same for both feature variations.
	let g = gsub(&mut font)?;
	assert_eq!(feature_tags(g)?, [CCMP, RLIG]);
	assert_eq!(lookups(g)?.len(), 2);
	assert_eq!(variations(g)?.feature_variation_record.len(), 1);
	assert_eq!(substitution_features(g, 0)?, [(0, CCMP), (1, RLIG)]);
	Ok(())
}

#[test]
fn test_add_feature_variations_existing_condition_sorted() -> TestResult {
	// Add 'rlig' first, then 'ccmp' with the same condition: 'ccmp' is inserted
	// before 'rlig' in the FeatureList, and the FeatureTableSubstitution records
	// must still be sorted by FeatureIndex.
	let mut font = varfont()?;
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (0.5, 1.0))], &[("A", "A.alt")]),
		&[RLIG],
	)?;
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (0.5, 1.0))], &[("B", "B.alt")]),
		&[CCMP],
	)?;

	let g = gsub(&mut font)?;
	assert_eq!(variations(g)?.feature_variation_record.len(), 1);
	assert_eq!(substitution_features(g, 0)?, [(0, CCMP), (1, RLIG)]);
	Ok(())
}

#[test]
fn test_add_feature_variations_null_condition() -> TestResult {
	for same_condition in [false, true] {
		for explicit_empty in [false, true] {
			let case = format!("same_condition={same_condition} explicit_empty={explicit_empty}");
			let mut font = varfont()?;
			add_feature_variations(
				&mut font,
				&one_rule(&[("wght", (-1.0, 1.0))], &[("A", "A.alt")]),
				&[CCMP],
			)?;
			let g = gsub(&mut font)?;
			let record = &mut g
				.feature_variations
				.as_deref_mut()
				.ok_or("no FeatureVariations")?
				.feature_variation_record[0];
			assert!(record.condition_set.is_none());
			if explicit_empty {
				record.condition_set = Some(Box::new(ot::ConditionSet {
					condition_count: Some(0),
					condition_table: Vec::new(),
				}));
			}

			roundtrip::<Gsub>(&mut font)?;
			let condition: &[(&str, (f64, f64))] = if same_condition {
				&[]
			} else {
				&[("wght", (0.5, 1.0))]
			};
			add_feature_variations(&mut font, &one_rule(condition, &[("B", "B.alt")]), &[RCLT])?;
			roundtrip::<Gsub>(&mut font)?;

			let g = gsub(&mut font)?;
			let records = &variations(g)?.feature_variation_record;
			assert_eq!(records.len(), if same_condition { 1 } else { 2 }, "{case}");
			assert_eq!(records[0].condition_set.is_some(), explicit_empty, "{case}");
			let original = &substitution(&records[0])?.substitution_record[0];
			assert_eq!(lookup_list_index(original)?, [0], "{case}");
			let new_feature = if same_condition {
				assert_eq!(
					substitution_features(g, 0)?,
					[(0, CCMP), (1, RCLT)],
					"{case}"
				);
				&substitution(&records[0])?.substitution_record[1]
			} else {
				assert_eq!(substitution_features(g, 0)?, [(0, CCMP)], "{case}");
				assert_eq!(substitution_features(g, 1)?, [(1, RCLT)], "{case}");
				let set = records[1]
					.condition_set
					.as_deref()
					.ok_or("no ConditionSet")?;
				let Some(ot::ConditionTable::Format1(c)) = set.condition_table[0].as_deref() else {
					return Err("not a format 1 condition".into());
				};
				assert_eq!(c.filter_range_min_value, 0.5, "{case}");
				&substitution(&records[1])?.substitution_record[0]
			};
			assert_eq!(lookup_list_index(new_feature)?, [1], "{case}");
		}
	}
	Ok(())
}

#[test]
fn test_add_feature_variations_null_substitution() -> TestResult {
	for same_condition in [false, true] {
		for explicit_empty in [false, true] {
			let case = format!("same_condition={same_condition} explicit_empty={explicit_empty}");
			let mut font = varfont()?;
			let condition = (0.5, 1.0);
			add_feature_variations(
				&mut font,
				&one_rule(&[("wght", condition)], &[("A", "A.alt")]),
				&[RVRN],
			)?;
			let g = gsub(&mut font)?;
			let record = &mut g
				.feature_variations
				.as_deref_mut()
				.ok_or("no FeatureVariations")?
				.feature_variation_record[0];
			if explicit_empty {
				let s = record
					.feature_table_substitution
					.as_deref_mut()
					.ok_or("no FeatureTableSubstitution")?;
				s.substitution_record = Vec::new();
				s.substitution_count = Some(0);
			} else {
				record.feature_table_substitution = None;
			}

			roundtrip::<Gsub>(&mut font)?;
			let new_condition = if same_condition {
				condition
			} else {
				(-1.0, 0.0)
			};
			add_feature_variations(
				&mut font,
				&one_rule(&[("wght", new_condition)], &[("B", "B.alt")]),
				&[CCMP],
			)?;
			roundtrip::<Gsub>(&mut font)?;

			let g = gsub(&mut font)?;
			let records = &variations(g)?.feature_variation_record;
			assert_eq!(records.len(), if same_condition { 1 } else { 2 }, "{case}");
			if !same_condition {
				if explicit_empty {
					assert_eq!(
						substitution(&records[0])?.substitution_record.len(),
						0,
						"{case}"
					);
				} else {
					assert!(records[0].feature_table_substitution.is_none(), "{case}");
				}
			}
			let last = records.last().ok_or("no records")?;
			let s = &substitution(last)?.substitution_record[0];
			assert_eq!(
				feature_tags(g)?[usize::from(s.feature_index)],
				CCMP,
				"{case}"
			);
			assert_eq!(lookup_list_index(s)?, [1], "{case}");
			assert_eq!(single_mapping(g, 1)?, [(B, B_ALT)], "{case}");
		}
	}
	Ok(())
}

/// `test_addFeatureVariations_extended_layout`, against the reference output of
/// fontTools.
#[test]
fn test_add_feature_variations_extended_layout() -> TestResult {
	let options = ConvertOptions {
		tables: Some(&["GSUB"]),
		..Default::default()
	};
	let substitutions = one_rule(&[("wght", (0.5, 1.0))], &[("A", "A.alt")]);
	for existing in ["plain", "existing"] {
		let fixture = data(&format!("extended_{existing}.ttx"));
		for (tag, tag_name) in [(RVRN, "rvrn"), (RCLT, "rclt")] {
			let expected = data(&format!("extended_{existing}_{tag_name}.expected.ttx"));

			let mut reference = font_from_ttx(&fixture)?;
			add_feature_variations(&mut reference, &substitutions, &[tag])?;
			roundtrip::<Gsub>(&mut reference)?;
			expect_ttx(&mut reference, &expected, &["GSUB"])?;

			for extended_header in [false, true] {
				for extended_formats in [false, true] {
					let mut font = font_from_ttx(&fixture)?;
					if extended_header {
						upper_tables(&mut font, &options)?;
					}
					convert_layout_formats(gsub(&mut font)?, extended_formats)?;
					roundtrip::<Gsub>(&mut font)?;
					add_feature_variations(&mut font, &substitutions, &[tag])?;
					assert_eq!(
						gsub(&mut font)?.version,
						if extended_header {
							0x0001_0002
						} else {
							0x0001_0001
						}
					);
					roundtrip::<Gsub>(&mut font)?;
					lower_tables(&mut font, &options)?;
					expect_ttx(&mut font, &expected, &["GSUB"])?;
				}
			}
		}
	}
	Ok(())
}

/// `addFeatureVariationsRaw(font, font[tag].table, conditions)`.
fn add_raw<T: TableType + Table + std::ops::DerefMut>(
	font: &mut Font,
	conditions: &[(AxisBox, Vec<u16>)],
) -> TestResult
where
	T::Target: OtlTable,
{
	font.with_table(T::TAG, |table, font| {
		let table = (*table)
			.as_any_mut()
			.downcast_mut::<T>()
			.ok_or(fontoxide_ttlib::Error::WrongTableType(T::TAG))?;
		add_feature_variations_raw(font, &mut **table, conditions, &[RVRN])
	})?;
	Ok(())
}

/// `test_addFeatureVariationsRaw_extended_layout`, against the reference output
/// of fontTools.
#[test]
fn test_add_feature_variations_raw_extended_layout() -> TestResult {
	fn run<T: TableType + Table + std::ops::DerefMut>(name: &str) -> TestResult
	where
		T::Target: OtlTable,
	{
		let options = ConvertOptions {
			tables: Some(&[name]),
			..Default::default()
		};
		let fixture = data(&format!("raw_{name}.ttx"));
		let expected = data(&format!("raw_{name}.expected.ttx"));
		let conditions = vec![(bx(&[("wght", (0.5, 1.0))]), vec![0])];

		let mut reference = font_from_ttx(&fixture)?;
		add_raw::<T>(&mut reference, &conditions)?;
		roundtrip::<T>(&mut reference)?;
		expect_ttx(&mut reference, &expected, &[name])?;

		for extended_header in [false, true] {
			let mut font = font_from_ttx(&fixture)?;
			if extended_header {
				upper_tables(&mut font, &options)?;
			}
			roundtrip::<T>(&mut font)?;
			add_raw::<T>(&mut font, &conditions)?;
			roundtrip::<T>(&mut font)?;
			let version = font.with_table(T::TAG, |t, _| {
				let t = (*t)
					.as_any_mut()
					.downcast_mut::<T>()
					.ok_or(fontoxide_ttlib::Error::WrongTableType(T::TAG))?;
				Ok(*t.layout_parts().version)
			})?;
			assert_eq!(
				version,
				if extended_header {
					0x0001_0002
				} else {
					0x0001_0001
				}
			);
			lower_tables(&mut font, &options)?;
			expect_ttx(&mut font, &expected, &[name])?;
		}
		Ok(())
	}
	run::<Gsub>("GSUB")?;
	run::<Gpos>("GPOS")
}

/// The GSUB of the fixtures of `Tests/varLib/mutator_test.py` that only
/// `addFeatureVariations` builds.
#[test]
fn mutator_fixture_null_condition_set() -> TestResult {
	let path = format!(
		"{}/tests/data/mutator/null_condition_set.ttx",
		env!("CARGO_MANIFEST_DIR")
	);
	let mut font = font_from_ttx(&path)?;
	font.remove(Gsub::TAG);
	add_feature_variations(
		&mut font,
		&one_rule(&[("wght", (-1.0, 1.0))], &[("A", "A.alt")]),
		&[CCMP],
	)?;
	// The fixture is a whole font: compare the GSUB part only.
	let gsub_part = |ttx: &str| -> TestResult<String> {
		let ttx = ttx.replace("\r\n", "\n");
		let start = ttx.find("  <GSUB>").ok_or("no GSUB")?;
		let end = ttx.find("  </GSUB>").ok_or("no GSUB")?;
		Ok(ttx[start..end].to_owned())
	};
	let actual = gsub_part(&to_ttx(&mut font, &["GSUB"])?)?;
	let expected = gsub_part(&std::fs::read_to_string(&path)?)?;
	assert_eq!(actual, expected);
	Ok(())
}

/// `_test_linear`.
fn linear(n: usize) {
	let mut conds = Vec::new();
	for i in 0..n {
		let end = i as f64 / n as f64;
		let start = end - 1.0;
		let region = vec![bx(&[("X", (start, end))])];
		let key = format!("g{}", format_g(start, 2).to_ascii_lowercase());
		let value = format!("g{}", format_g(end, 2).to_ascii_lowercase());
		conds.push((region, subst(&[(&key, &value)])));
	}
	let overlaps = overlay_feature_variations(&conds);
	assert_eq!(overlaps.len(), 2 * n - 1, "{overlaps:?}");
}

#[test]
fn test_linear() {
	linear(10);
}

/// `_test_quadratic`.
fn quadratic(n: usize) {
	let mut conds = Vec::new();
	for i in 1..=n {
		let region = vec![bx(&[
			("X", (0.0, i as f64 / n as f64)),
			("Y", (0.0, (n + 1 - i) as f64 / n as f64)),
		])];
		let key = i.to_string();
		let value = (n + 1 - i).to_string();
		conds.push((region, subst(&[(&key, &value)])));
	}
	let overlaps = overlay_feature_variations(&conds);
	assert_eq!(overlaps.len(), n * (n + 1) / 2, "{overlaps:?}");
}

#[test]
fn test_quadratic() {
	quadratic(10);
}

/// `_match_condition`, with `_merge_substitutions`.
fn match_condition(
	location: &[(&str, f64)],
	overlaps: &[(AxisBox, Vec<std::sync::Arc<Substitution>>)],
) -> TestResult<Substitution> {
	for (bx, substitutions) in overlaps {
		for (tag, coord) in location {
			let &(start, end) = bx.get(*tag).ok_or("KeyError")?;
			if start <= *coord && *coord <= end {
				let mut merged = Substitution::new();
				for s in substitutions {
					merged.extend(s.iter().map(|(k, v)| (k.clone(), v.clone())));
				}
				return Ok(merged);
			}
		}
	}
	// No match.
	Ok(Substitution::new())
}

/// `{0: 0, ...}` of the overlap tests: the glyph names are numbers there.
fn numbers(keys: &[u32]) -> Substitution {
	keys.iter()
		.map(|k| (k.to_string(), k.to_string()))
		.collect()
}

#[test]
fn test_overlaps_1() -> TestResult {
	// https://github.com/fonttools/fonttools/issues/1400
	let conds = rules(&[
		(&[bx(&[("abcd", (4.0, 9.0))])], numbers(&[0])),
		(&[bx(&[("abcd", (5.0, 10.0))])], numbers(&[1])),
		(&[bx(&[("abcd", (0.0, 8.0))])], numbers(&[2])),
		(&[bx(&[("abcd", (3.0, 7.0))])], numbers(&[3])),
	]);
	let overlaps = overlay_feature_variations(&conds);
	for (coord, expected) in [
		(0.0, &[2][..]),
		(1.0, &[2]),
		(3.0, &[2, 3]),
		(4.0, &[0, 2, 3]),
		(5.0, &[0, 1, 2, 3]),
		(7.0, &[0, 1, 2, 3]),
		(8.0, &[0, 1, 2]),
		(9.0, &[0, 1]),
		(10.0, &[1]),
	] {
		assert_eq!(
			match_condition(&[("abcd", coord)], &overlaps)?,
			numbers(expected),
			"abcd={coord}"
		);
	}
	Ok(())
}

#[test]
fn test_overlaps_2() -> TestResult {
	// https://github.com/fonttools/fonttools/issues/1400
	let conds = rules(&[
		(&[bx(&[("abcd", (1.0, 9.0))])], numbers(&[0])),
		(&[bx(&[("abcd", (8.0, 10.0))])], numbers(&[1])),
		(&[bx(&[("abcd", (3.0, 4.0))])], numbers(&[2])),
		(&[bx(&[("abcd", (1.0, 10.0))])], numbers(&[3])),
	]);
	let overlaps = overlay_feature_variations(&conds);
	for (coord, expected) in [
		(0.0, &[][..]),
		(1.0, &[0, 3]),
		(2.0, &[0, 3]),
		(3.0, &[0, 2, 3]),
		(5.0, &[0, 3]),
		(10.0, &[1, 3]),
	] {
		assert_eq!(
			match_condition(&[("abcd", coord)], &overlaps)?,
			numbers(expected),
			"abcd={coord}"
		);
	}
	Ok(())
}

#[test]
fn test_overlay_box() {
	// https://github.com/fonttools/fonttools/issues/3003
	let top = bx(&[("opsz", (0.75, 1.0)), ("wght", (0.5, 1.0))]);
	let bot = bx(&[("wght", (0.25, 1.0))]);
	let (intersection, remainder) = overlay_box(&top, &bot);
	assert_eq!(
		intersection,
		Some(bx(&[("opsz", (0.75, 1.0)), ("wght", (0.5, 1.0))]))
	);
	assert_eq!(remainder, Some(bx(&[("wght", (0.25, 1.0))])));
}

/// The doctest of `overlayFeatureVariations`.
#[test]
fn doctest_overlay_feature_variations() {
	let cond_subst = rules(&[
		(
			&[bx(&[("wght", (0.5, 1.0))])],
			subst(&[("dollar", "dollar.rvrn")]),
		),
		(
			&[bx(&[("wght", (0.5, 1.0))])],
			subst(&[("dollar", "dollar.rvrn")]),
		),
		(
			&[bx(&[("wdth", (0.5, 1.0))])],
			subst(&[("cent", "cent.rvrn")]),
		),
		(
			&[bx(&[("wght", (0.5, 1.0)), ("wdth", (-1.0, 1.0))])],
			subst(&[("dollar", "dollar.rvrn")]),
		),
	]);
	let actual: Vec<(AxisBox, Vec<Substitution>)> = overlay_feature_variations(&cond_subst)
		.into_iter()
		.map(|(b, s)| (b, s.iter().map(|s| (**s).clone()).collect()))
		.collect();
	let expected = vec![
		(
			bx(&[("wdth", (0.5, 1.0)), ("wght", (0.5, 1.0))]),
			vec![
				subst(&[("dollar", "dollar.rvrn")]),
				subst(&[("cent", "cent.rvrn")]),
			],
		),
		(
			bx(&[("wdth", (0.5, 1.0))]),
			vec![subst(&[("cent", "cent.rvrn")])],
		),
		(
			bx(&[("wght", (0.5, 1.0))]),
			vec![subst(&[("dollar", "dollar.rvrn")])],
		),
	];
	assert_eq!(actual, expected);
}
